using System;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Conquest.WorldMap;
public static class BakeLocalCampaignNavigation {
 static bool Overlap(Vector2 a,Vector2 b,Vector2 c,Vector2 center,float half){var vertices=new[]{a-center,b-center,c-center};var edges=new[]{Vector2.right,Vector2.up,new Vector2(-(b-a).y,(b-a).x),new Vector2(-(c-b).y,(c-b).x),new Vector2(-(a-c).y,(a-c).x)};foreach(var axis in edges){float min=float.PositiveInfinity,max=float.NegativeInfinity;foreach(var p in vertices){float v=Vector2.Dot(p,axis);min=Mathf.Min(min,v);max=Mathf.Max(max,v);}float radius=half*(Mathf.Abs(axis.x)+Mathf.Abs(axis.y));if(min>radius||max<-radius)return false;}return true;}
 public static string Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");var c=UnityEngine.Object.FindAnyObjectByType<WorldMapCampaignController>();var m=c.streamer.manifest;var data=ScriptableObject.CreateInstance<WorldMapLocalNavigation>();data.sourceSHA256=m.sourceSHA256;data.cellSize=62.5f;data.columns=Mathf.CeilToInt(m.worldSize.x/data.cellSize);data.rows=Mathf.CeilToInt(m.worldSize.y/data.cellSize);int count=data.columns*data.rows;data.blocked=new byte[count];data.heights=new float[count];var sources=new Dictionary<int,TerrainData>();foreach(var sector in m.sectors){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/WorldMap/Campaign/Sectors/"+sector.id+".prefab");sources.Add(sector.row*8+sector.column,prefab.GetComponent<WorldMapCampaignSector>().terrain.terrainData);}
  float Height(float x,float z){x=Mathf.Clamp(x,0,m.worldSize.x-.01f);z=Mathf.Clamp(z,0,m.worldSize.y-.01f);int col=Mathf.FloorToInt(x/m.sectorSize),row=Mathf.FloorToInt(z/m.sectorSize);var t=sources[row*8+col];return t.GetInterpolatedHeight((x-col*m.sectorSize)/t.size.x,(z-row*m.sectorSize)/t.size.z)+m.sectors.First(q=>q.column==col&&q.row==row).origin.y;}
  float half=data.cellSize*.5f;for(int i=0;i<count;i++){float x=(i%data.columns+.5f)*data.cellSize,z=(i/data.columns+.5f)*data.cellSize;float h=Height(x,z);data.heights[i]=h;if(h<=m.seaHeight+.5f){data.blocked[i]=1;continue;}float slope=0;for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++){if(dx==0&&dz==0)continue;float other=Height(x+dx*half,z+dz*half);slope=Mathf.Max(slope,Mathf.Atan(Mathf.Abs(other-h)/(half*Mathf.Sqrt(dx*dx+dz*dz)))*Mathf.Rad2Deg);}if(slope>data.maxSlope)data.blocked[i]=2;}
  int triangles=0;foreach(var file in System.IO.Directory.GetFiles("Assets/WorldMap/Campaign/Water","*.asset")){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(file.Replace('\\','/'));if(!mesh)continue;var v=mesh.vertices;var tri=mesh.triangles;for(int k=0;k<tri.Length;k+=3){var a=new Vector2(v[tri[k]].x,v[tri[k]].z);var b=new Vector2(v[tri[k+1]].x,v[tri[k+1]].z);var d=new Vector2(v[tri[k+2]].x,v[tri[k+2]].z);int x0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.x,b.x,d.x)/data.cellSize),0,data.columns-1),x1=Mathf.Clamp(Mathf.FloorToInt(Mathf.Max(a.x,b.x,d.x)/data.cellSize),0,data.columns-1),z0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.y,b.y,d.y)/data.cellSize),0,data.rows-1),z1=Mathf.Clamp(Mathf.FloorToInt(Mathf.Max(a.y,b.y,d.y)/data.cellSize),0,data.rows-1);for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++){int i=z*data.columns+x;if(data.blocked[i]==0&&Overlap(a,b,d,new Vector2((x+.5f)*data.cellSize,(z+.5f)*data.cellSize),half))data.blocked[i]=3;}triangles++;}}
  const string path="Assets/WorldMap/Campaign/LocalNavigation.asset";var existing=AssetDatabase.LoadAssetAtPath<WorldMapLocalNavigation>(path);if(existing){EditorUtility.CopySerialized(data,existing);UnityEngine.Object.DestroyImmediate(data);data=existing;}else AssetDatabase.CreateAsset(data,path);c.navigation=data;foreach(var city in new[]{c.cityA,c.cityB}){var gate=city.GetComponent<WorldMapSettlementTarget>();if(data.Walkable(gate.entrance))continue;int nearest=-1;float best=140*140;for(int i=0;i<count;i++){if(data.blocked[i]!=0)continue;var center=data.Center(i);float distance=(new Vector2(center.x,center.z)-new Vector2(gate.entrance.x,gate.entrance.z)).sqrMagnitude;if(distance<best){best=distance;nearest=i;}}if(nearest<0)throw new Exception("No dry entrance near "+city.name);gate.entrance=data.Center(nearest);EditorUtility.SetDirty(gate);}c.demoRoute[c.demoRoute.Length-1]=c.cityB.GetComponent<WorldMapSettlementTarget>().entrance;EditorUtility.SetDirty(data);UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(c.gameObject.scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(c.gameObject.scene);AssetDatabase.SaveAssets();int land=data.blocked.Count(b=>b==0);string report=$"{data.columns}x{data.rows}, {land}/{count} walkable cells, {triangles} water triangles. A={data.Walkable(c.demoRoute[0])}, B={data.Walkable(c.demoRoute[c.demoRoute.Length-1])}";System.IO.File.WriteAllText("Docs/LocalNavigationBake.txt",report);return report;
 }
}
